package io.tornado.reporting;
import io.tornado.notification.TelegramNotificationService;import io.tornado.persistence.*;import org.slf4j.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.time.format.*;import java.util.*;import java.util.stream.*;
@Service public class DailyTelegramReportService{public static final ZoneId TEHRAN=ZoneId.of("Asia/Tehran");private static final Logger log=LoggerFactory.getLogger(DailyTelegramReportService.class);private final MixTradeSimulationRepository simulations;private final TelegramDailyReportRepository reports;private final AppSettingsRepository settings;private final TelegramNotificationService telegram;private final Clock clock;
 @org.springframework.beans.factory.annotation.Autowired public DailyTelegramReportService(MixTradeSimulationRepository s,TelegramDailyReportRepository r,AppSettingsRepository a,TelegramNotificationService t){this(s,r,a,t,Clock.systemUTC());}DailyTelegramReportService(MixTradeSimulationRepository s,TelegramDailyReportRepository r,AppSettingsRepository a,TelegramNotificationService t,Clock c){simulations=s;reports=r;settings=a;telegram=t;clock=c;}
 @Transactional public synchronized void sendPreviousDay(){send(LocalDate.now(clock.withZone(TEHRAN)).minusDays(1));}
 @Transactional public void send(LocalDate date){if(!settings.findById(1).orElseThrow().isTelegramDailyReportEnabled()||!telegram.configured())return;TelegramDailyReport report=reports.findByReportDate(date).orElseGet(()->create(date));if(report.getStatus()==TelegramDailyReport.Status.SENT||report.getAttempts()>=3)return;Summary summary=summarize(date);var result=telegram.send(format(summary));if(result.status()==TelegramNotificationService.DeliveryResult.Status.SENT)report.sent(result.messageId());else report.failed(result.detail());}
 private TelegramDailyReport create(LocalDate date){Instant start=date.atStartOfDay(TEHRAN).toInstant(),end=date.plusDays(1).atStartOfDay(TEHRAN).toInstant();try{return reports.saveAndFlush(new TelegramDailyReport(date,start,end,clock.instant()));}catch(DataIntegrityViolationException e){return reports.findByReportDate(date).orElseThrow();}}
 @Transactional public synchronized void retryFailed(){for(TelegramDailyReport r:reports.findByStatusAndAttemptsLessThanOrderByReportDateAsc(TelegramDailyReport.Status.FAILED,3))try{send(r.getReportDate());}catch(Exception e){log.warn("Daily Telegram retry failed for {}: {}",r.getReportDate(),e.getMessage());}}
 public Summary summarize(LocalDate date){Instant start=date.atStartOfDay(TEHRAN).toInstant(),end=date.plusDays(1).atStartOfDay(TEHRAN).toInstant();List<MixTradeSimulation>created=simulations.findByOpenedAtGreaterThanEqualAndOpenedAtLessThan(start,end),closed=simulations.findByClosedAtGreaterThanEqualAndClosedAtLessThan(start,end);long targets=closed.stream().filter(x->x.getStatus()==MixTradeSimulation.Status.TARGET_HIT).count(),stops=closed.stream().filter(x->x.getStatus()==MixTradeSimulation.Status.STOP_LOSS_HIT).count(),pending=created.stream().filter(x->x.getClosedAt()==null||!x.getClosedAt().isBefore(end)).count(),longs=created.stream().filter(x->x.getDirection()==Direction.UP).count();double pnl=closed.stream().map(MixTradeSimulation::getResultPercent).filter(Objects::nonNull).mapToDouble(Double::doubleValue).sum();Map<String,MethodStat>methods=new HashMap<>();for(MixTradeSimulation s:created)for(String method:s.getMethodNames())methods.computeIfAbsent(method,MethodStat::new).add(s,end);Map<String,MixStat>mixes=new HashMap<>();for(MixTradeSimulation s:created)mixes.computeIfAbsent(s.getCoin().getSymbol()+"|"+s.getHorizonSeconds()+"|"+String.join(" + ",s.getMethodNames()),x->new MixStat(s)).add(s,end);return new Summary(date,created.size(),targets,stops,pending,simulations.countByStatus(MixTradeSimulation.Status.OPEN),longs,created.size()-longs,pnl,methods.values().stream().sorted(Comparator.comparingLong(MethodStat::executions).reversed()).toList(),mixes.values().stream().sorted(Comparator.comparingLong(MixStat::executions).reversed()).toList());}
 public String format(Summary s){StringBuilder b=new StringBuilder("📊 TORNIDO DAILY REPORT\n📅 ").append(s.date.format(DateTimeFormatter.ofPattern("dd MMM uuuu",Locale.ENGLISH))).append("\n🕛 Tehran Time\n\n🚀 Signals Created: ").append(s.created).append("\n✅ Target Hits: ").append(s.targets).append("\n❌ Stop Loss Hits: ").append(s.stops).append("\n⏳ New Signals Still Open: ").append(s.pending).append("\n📌 Total Currently Open: ").append(s.totalOpen);long closed=s.targets+s.stops;b.append("\n\n🎯 Closed Hit Rate: ").append(closed==0?"—":String.format("%d / %d = %.1f%%",s.targets,closed,s.targets*100.0/closed)).append("\n🟢 LONG Signals: ").append(s.longs).append("\n🔴 SHORT Signals: ").append(s.shorts).append("\n💵 Net Simulation P&L: ").append(String.format("%+.3f%%",s.netPnl)).append("\n\n🧠 METHOD PERFORMANCE");int i=0;for(MethodStat m:s.methods){if(i++>=10)break;b.append("\n\n").append(i<=3?List.of("🥇","🥈","🥉").get(i-1):"•").append(" ").append(m.name).append("\n🚀 Executed: ").append(m.executions).append(" | ✅ ").append(m.targets).append(" | ❌ ").append(m.stops).append(" | ⏳ ").append(m.pending).append("\n🎯 Hit Rate: ").append(m.closed()==0?"—":String.format("%.1f%%",m.targets*100.0/m.closed()));}List<MixStat>eligible=s.mixes.stream().filter(x->x.closed()>=3).toList();b.append("\n\n🏆 MIX PERFORMANCE\n");if(eligible.isEmpty())b.append("Not enough closed simulations for reliable daily ranking.");else{MixStat best=eligible.stream().max(Comparator.comparingDouble(MixStat::rate)).orElseThrow(),worst=eligible.stream().min(Comparator.comparingDouble(MixStat::rate)).orElseThrow(),most=s.mixes.getFirst();appendMix(b,"Best",best);appendMix(b,"Worst",worst);appendMix(b,"Most Executed",most);}return b.toString();}
 private void appendMix(StringBuilder b,String title,MixStat m){b.append("\n\n").append(title).append(": ").append(m.methods).append("\n🪙 ").append(m.coin).append(" · ⏱ ").append(m.horizon).append("s · 🚀 ").append(m.executions).append(" · ✅ ").append(m.targets).append(" · ❌ ").append(m.stops).append(" · ⏳ ").append(m.pending).append(" · 🎯 ").append(m.closed()==0?"—":String.format("%.1f%%",m.rate()));}
 public record Summary(LocalDate date,long created,long targets,long stops,long pending,long totalOpen,long longs,long shorts,double netPnl,List<MethodStat>methods,List<MixStat>mixes){}public static class MethodStat{final String name;long executions,targets,stops,pending,longs,shorts;MethodStat(String n){name=n;}void add(MixTradeSimulation s,Instant cutoff){executions++;if(s.getDirection()==Direction.UP)longs++;else shorts++;if(s.getClosedAt()==null||!s.getClosedAt().isBefore(cutoff))pending++;else if(s.getStatus()==MixTradeSimulation.Status.TARGET_HIT)targets++;else if(s.getStatus()==MixTradeSimulation.Status.STOP_LOSS_HIT)stops++;}public String name(){return name;}public long executions(){return executions;}public long targets(){return targets;}public long stops(){return stops;}public long pending(){return pending;}public long longs(){return longs;}public long shorts(){return shorts;}long closed(){return targets+stops;}}
 public static class MixStat{final String coin,methods;final long horizon;long executions,targets,stops,pending;MixStat(MixTradeSimulation s){coin=s.getCoin().getSymbol();methods=String.join(" + ",s.getMethodNames());horizon=s.getHorizonSeconds();}void add(MixTradeSimulation s,Instant cutoff){executions++;if(s.getClosedAt()==null||!s.getClosedAt().isBefore(cutoff))pending++;else if(s.getStatus()==MixTradeSimulation.Status.TARGET_HIT)targets++;else if(s.getStatus()==MixTradeSimulation.Status.STOP_LOSS_HIT)stops++;}public long executions(){return executions;}long closed(){return targets+stops;}double rate(){return closed()==0?0:targets*100.0/closed();}}
}
